    void budget(int count){var calls=List.copyOf(observed.calls);observed.stop();var domain=calls.stream().filter(DeviceGroupIntegrationTest.Call::readOnly).toList();assertThat(domain).hasSize(count).allMatch(c->c.isolation()==Connection.TRANSACTION_REPEATABLE_READ&&c.sql().startsWith("SELECT "));assertThat(domain).noneMatch(c->c.sql().contains("SELECT *")||c.sql().contains("FOR UPDATE")||c.sql().contains("clock_")||c.sql().contains("app_users")||c.sql().contains("name")||c.sql().contains("notification_"));}
    @Test void commandActualRcLockOrderAndOneStatementClockAreIndependentOfMetadataRevision()throws Exception{String card=card();clearInvocations(clock);observed.start();write(card,true,DEVICE,0,"locks");var calls=List.copyOf(observed.calls);observed.stop();List<String> sql=calls.stream().map(DeviceGroupIntegrationTest.Call::sql).toList();int guard=index(sql,"SELECT id FROM security_management_lock"),parent=index(sql,"SELECT id FROM sim_cards"),device=index(sql,"SELECT id FROM devices"),current=index(sql,"SELECT card_id,tenant_id,device_id,revision,recorded_at FROM sim_card_associations");assertThat(guard).isGreaterThanOrEqualTo(0);assertThat(parent).isGreaterThan(guard);assertThat(device).isGreaterThan(parent);assertThat(current).isGreaterThan(device);assertThat(sql.get(parent)).endsWith("FOR UPDATE");assertThat(sql.get(device)).endsWith("FOR UPDATE");assertThat(sql.get(current)).endsWith("FOR UPDATE");assertThat(calls.stream().filter(c->c.sql().contains("FOR UPDATE")).toList()).allMatch(c->!c.readOnly()&&c.isolation()==Connection.TRANSACTION_READ_COMMITTED);verify(clock,times(1)).now();assertThat(history(card,"").at("/items/0/recorded_at")).isEqualTo(state(card).get("recorded_at"));}
    int index(List<String> calls,String prefix){for(int i=0;i<calls.size();i++)if(calls.get(i).startsWith(prefix))return i;return -1;}
