    @Test void twoIdentitiesRacingDifferentCardsForOneDeviceHaveExactlyOneWinner()throws Exception{String a=card(),b=card(),other=actor("race-device",List.of("sim-cards:read","device:read","sim-cards:bind"));var second=input(DEVICE,0,"");try(var pool=Executors.newFixedThreadPool(2)){var go=new CountDownLatch(1);var one=pool.submit(()->{go.await();return f.call(POST,BASE+"/"+a+"/bind",f.root,"tenant-a","one",input(DEVICE,0,"")).andReturn().getResponse().getStatus();});var two=pool.submit(()->{go.await();return f.call(POST,BASE+"/"+b+"/bind",other,"tenant-a","two",second).andReturn().getResponse().getStatus();});go.countDown();assertThat(List.of(one.get(15,TimeUnit.SECONDS),two.get(15,TimeUnit.SECONDS))).containsExactlyInAnyOrder(200,409);}assertThat(count("sim_card_associations")).isEqualTo(1);assertThat(count("sim_card_association_changes")).isEqualTo(1);}
