    @Test void concurrentManualMetadataEditAndAssociationHaveIndependentCasAndHistories()throws Exception{String card=card(),metadataActor=actor("race-metadata",List.of("sim-cards:read","sim-cards:write"));var metadata=metadata(null,0L);metadata.put("source_note","independent metadata edit");try(var pool=Executors.newFixedThreadPool(2)){var go=new CountDownLatch(1);var one=pool.submit(()->{go.await();return write(card,true,DEVICE,0,"association");});var two=pool.submit(()->{go.await();return f.call(PUT,BASE+"/"+card,metadataActor,"tenant-a","metadata",metadata).andExpect(status().isOk());});go.countDown();assertThat(one.get(15,TimeUnit.SECONDS).at("/association/revision").longValue()).isEqualTo(1);two.get(15,TimeUnit.SECONDS);}assertThat(state(card).get("revision").longValue()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT revision FROM sim_cards WHERE id=?",Long.class,card)).isEqualTo(1);assertThat(count("sim_card_changes")).isEqualTo(2);assertThat(count("sim_card_association_changes")).isEqualTo(1);}
    @Test void cachedVirginUnbindCannotForgeAChangedRevisionOneEmptyReceipt()throws Exception{
        String card=card(),key="forged-virgin-unbind";
        var original=write(card,false,DEVICE,0,key);
        assertThat(original.get("changed").asBoolean()).isFalse();
        assertThat(original.at("/association/revision").longValue()).isZero();
        assertThat(count("sim_card_associations")).isZero();
        var forged=(com.fasterxml.jackson.databind.node.ObjectNode)original.deepCopy();
        forged.put("changed",true);
        var association=(com.fasterxml.jackson.databind.node.ObjectNode)forged.get("association");
        association.put("revision",1);association.put("recorded_at","2026-01-02T03:04:05.123456Z");
        assertThat(jdbc.update("UPDATE idempotency_records SET response_json=? WHERE user_id='bootstrap-admin' AND operation='sim-card-unbind' AND idem_key=?",json.writeValueAsString(forged),key)).isEqualTo(1);
        String before=facts(Set.of());long auditBefore=count("audit_log"),idemBefore=count("idempotency_records"),historyBefore=count("sim_card_association_changes");
        clearInvocations(clock);
        var replay=f.call(POST,BASE+"/"+card+"/unbind",f.root,"tenant-a",key,input(DEVICE,0,""));
        // Check the complete zero-write interval even when the final status assertion is RED.
        assertThat(facts(Set.of())).isEqualTo(before);
        assertThat(count("audit_log")).isEqualTo(auditBefore);
        assertThat(count("idempotency_records")).isEqualTo(idemBefore);
        assertThat(count("sim_card_association_changes")).isEqualTo(historyBefore);
        assertThat(count("sim_card_associations")).isZero();
        verify(clock,never()).now();
        replay.andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("SIM_BINDING_READ_UNCONFIRMED"));
    }
    void concurrent(Runnable action){try(var pool=Executors.newSingleThreadExecutor()){pool.submit(action).get(10,TimeUnit.SECONDS);}catch(Exception e){throw new AssertionError("bounded association concurrency failed",e);}}
    @Test void historyCurrentVersionCountAndPageRemainOneOldRrSnapshotDuringUnbindCommit()throws Exception{String card=card();write(card,true,DEVICE,0,"before");observed.beforePage=()->concurrent(()->{try{write(card,false,DEVICE,1,"during");}catch(Exception e){throw new AssertionError(e);}});observed.start();var old=history(card,"");observed.stop();assertThat(old.get("total").longValue()).isEqualTo(1);assertThat(old.at("/items/0/revision").longValue()).isEqualTo(1);assertThat(old.at("/items/0/to_device_id").asText()).isEqualTo(DEVICE);var next=history(card,"");assertThat(next.get("total").longValue()).isEqualTo(2);assertThat(next.at("/items/0/operation").asText()).isEqualTo("UNBIND");}
